// Fixture independence, measured on purpose.
//
// Every id and every timestamp below is generated by this file. Nothing is
// copied from the incident that motivated the correction: no `ffb357bf…`
// issue, no `55ab48d9…` run, no `requestedAt` from 29 or 30 September. A
// regression gate that replays the incident's own rows proves the incident
// recurred, not that the defect is closed.

import { randomUUID } from "node:crypto";
import { eq } from "drizzle-orm";
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
import {
  activityLog,
  agentRuntimeState,
  agentTaskSessions,
  companySkills,
  companySkillVersions,
  agents,
  environmentLeases,
  agentWakeupRequests,
  companies,
  createDb,
  heartbeatRunEvents,
  heartbeatRuns,
  issueRecoveryActions,
  issues,
} from "@paperclipai/db";
import {
  getEmbeddedPostgresTestSupport,
  startEmbeddedPostgresTestDatabase,
} from "./helpers/embedded-postgres.js";

const mockTelemetryClient = vi.hoisted(() => ({ track: vi.fn() }));
vi.mock("../telemetry.ts", () => ({ getTelemetryClient: () => mockTelemetryClient }));

// Queue promotion may dispatch a run. Keep this regression independent of a
// real provider, as in the orphan-lease-release suite.
vi.mock("../adapters/index.ts", async () => {
  const actual = await vi.importActual<typeof import("../adapters/index.ts")>("../adapters/index.ts");
  return {
    ...actual,
    getServerAdapter: vi.fn(() => ({
      supportsLocalAgentJwt: false,
      execute: vi.fn(async () => ({
        exitCode: 0, signal: null, timedOut: false, errorMessage: null,
        summary: "Orphan deferred-wake test run.", provider: "test", model: "test-model",
      })),
    })),
  };
});

import { heartbeatService } from "../services/heartbeat.ts";
import { drainHeartbeatRunsToQuiescence } from "./helpers/drain-heartbeat-runs.js";
import { recoveryService } from "../services/recovery/service.ts";

const embeddedPostgresSupport = await getEmbeddedPostgresTestSupport();
const describeEmbeddedPostgres = embeddedPostgresSupport.supported ? describe : describe.skip;

if (!embeddedPostgresSupport.supported) {
  console.warn(
    `Skipping embedded Postgres orphan deferred-wake tests on this host: ${
      embeddedPostgresSupport.reason ?? "unsupported environment"
    }`,
  );
}

describeEmbeddedPostgres("deferred wake queue orphaned by the stale-lock sweep", () => {
  let db!: ReturnType<typeof createDb>;
  let tempDb: Awaited<ReturnType<typeof startEmbeddedPostgresTestDatabase>> | null = null;

  beforeAll(async () => {
    tempDb = await startEmbeddedPostgresTestDatabase("paperclip-orphan-deferred-wake-");
    db = createDb(tempDb.connectionString);
  }, 120_000);

  afterEach(async () => {
    await drainHeartbeatRunsToQuiescence(db, heartbeatService(db));
    mockTelemetryClient.track.mockClear();
    await db.delete(issueRecoveryActions);
    await db.delete(environmentLeases);
    await db.delete(activityLog);
    // Terminalizing a run appends a run event, and runs reference both their
    // originating wake and their lease, so both go before the runs.
    await db.delete(heartbeatRunEvents);
    await db.delete(agentTaskSessions);
    await db.delete(heartbeatRuns);
    await db.delete(agentWakeupRequests);
    await db.delete(issues);
    // Dispatch writes agent runtime state for the run it promotes.
    await db.delete(agentRuntimeState);
    await db.delete(companySkillVersions);
    await db.delete(companySkills);
    await db.delete(agents);
    await db.delete(companies);
  });

  afterAll(async () => {
    await tempDb?.cleanup();
  });

  async function seed() {
    const companyId = randomUUID();
    const agentId = randomUUID();
    await db.insert(companies).values({
      id: companyId,
      name: "Paperclip",
      issuePrefix: `T${companyId.replace(/-/g, "").slice(0, 6).toUpperCase()}`,
      // A promoted wake resolves its responsible user through the company, so a
      // company without one leaves the queue parked for a reason unrelated to
      // what these tests measure.
      defaultResponsibleUserId: "responsible-user",
      requireBoardApprovalForNewAgents: false,
    });
    await db.insert(agents).values({
      id: agentId,
      companyId,
      name: "Coder",
      role: "engineer",
      status: "active",
      adapterType: "codex_local",
      adapterConfig: {},
      runtimeConfig: {},
      permissions: {},
    });
    return { companyId, agentId };
  }

  /** A wake parked by an execution wait: no run, no comment ids, no blocker. */
  async function seedParkedExecutionWaitWake(input: {
    companyId: string;
    agentId: string;
    issueId: string;
  }) {
    const wakeId = randomUUID();
    await db.insert(agentWakeupRequests).values({
      id: wakeId,
      companyId: input.companyId,
      agentId: input.agentId,
      source: "on_demand",
      triggerDetail: "manual",
      reason: "issue_commented",
      // No `_paperclipWakeContext.wakeCommentIds`: this is the shape that the
      // pre-fix `strandedQueues` predicate could not match.
      payload: {
        issueId: input.issueId,
        executionWait: { reason: "execution_recovery", message: "Waiting for execution recovery." },
      },
      status: "deferred_issue_execution",
      requestedByActorType: "user",
      requestedByActorId: randomUUID(),
      requestedAt: new Date("2026-11-04T09:15:00.000Z"),
    });
    return wakeId;
  }

  it("drains a deferred wake when the sweep clears the issue lock (D1)", async () => {
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    // A terminal run still named by the issue's lock column: exactly the state
    // the sweep exists for.
    const staleRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: staleRunId,
      companyId,
      agentId,
      status: "succeeded",
      runtimeMode: "legacy",
      invocationSource: "automation",
      startedAt: new Date("2026-11-04T08:55:00.000Z"),
      finishedAt: new Date("2026-11-04T09:02:00.000Z"),
      contextSnapshot: { issueId, wakeReason: "issue_commented" },
    });
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Deferred queue orphaned by the stale-lock sweep",
      status: "in_progress",
      priority: "high",
      assigneeAgentId: agentId,
      executionRunId: staleRunId,
    });
    await seedParkedExecutionWaitWake({ companyId, agentId, issueId });

    const result = await heartbeatService(db).sweepStaleIssueLocks();

    expect(result.cleared).toBe(1);
    expect(result.issueIds).toEqual([issueId]);
    // D1: the cleared issue went back to the deferred-wake drain.
    expect(result.drainedRunIds).toEqual([staleRunId]);
    expect(result.drainFailures).toEqual([]);
  });

  it("resumes a stranded execution-wait wake once its blocker is gone (D3)", async () => {
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    const terminalRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: terminalRunId,
      companyId,
      agentId,
      status: "succeeded",
      runtimeMode: "legacy",
      invocationSource: "automation",
      startedAt: new Date("2026-11-04T08:55:00.000Z"),
      finishedAt: new Date("2026-11-04T09:02:00.000Z"),
      contextSnapshot: { issueId, wakeReason: "issue_commented" },
    });
    // The issue holds no lock: `executionRunId` is null, which is the stranded
    // precondition the predicate checks.
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Stranded execution wait with no blocker",
      status: "in_progress",
      priority: "high",
      assigneeAgentId: agentId,
    });
    const wakeId = await seedParkedExecutionWaitWake({ companyId, agentId, issueId });

    await heartbeatService(db).resumeQueuedRuns();

    // The wake left the deferred status instead of parking forever.
    const [wake] = await db
      .select({ status: agentWakeupRequests.status, runId: agentWakeupRequests.runId })
      .from(agentWakeupRequests)
      .where(eq(agentWakeupRequests.id, wakeId));
    expect(wake?.status).not.toBe("deferred_issue_execution");
  });

  it("leaves an execution-wait wake alone while its blocker is still active (D3 negative)", async () => {
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    const blockingRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: blockingRunId,
      companyId,
      agentId,
      status: "interrupted",
      runtimeMode: "legacy",
      invocationSource: "automation",
      errorCode: "orphaned_running_run",
      startedAt: new Date("2026-11-04T08:55:00.000Z"),
      finishedAt: new Date("2026-11-04T09:02:00.000Z"),
      contextSnapshot: { issueId },
    });
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Execution wait with a live blocker",
      status: "in_progress",
      priority: "high",
      assigneeAgentId: agentId,
    });
    const wakeId = await seedParkedExecutionWaitWake({ companyId, agentId, issueId });
    // An active reconciliation action is exactly what `resumeExecutionWaitComments`
    // requires, and what the widened predicate must still respect.
    await db.insert(issueRecoveryActions).values({
      companyId,
      sourceIssueId: issueId,
      status: "active",
      cause: "execution_owner_active",
      nextAction: "resume",
      kind: "execution_reconciliation",
      fingerprint: randomUUID(),
      evidence: { runId: blockingRunId },
    });

    await heartbeatService(db).resumeQueuedRuns();

    const [wake] = await db
      .select({ status: agentWakeupRequests.status })
      .from(agentWakeupRequests)
      .where(eq(agentWakeupRequests.id, wakeId));
    expect(wake?.status).toBe("deferred_issue_execution");
  });

  it("resumeExecutionWaitComments cannot resume without an active blocker (D2 documented limit)", async () => {
    // D2 records the limit rather than removing it: this native recovery path
    // requires `exists(issueRecoveryActions … executionBlockerPredicate())` in
    // its WHERE, so it cannot be the only route for an execution wait. The D3
    // widening of `strandedQueues` is what covers the gap; this test is the
    // negative control that the gap really was open.
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Execution wait with no recovery action at all",
      status: "in_progress",
      priority: "high",
      assigneeAgentId: agentId,
    });
    await seedParkedExecutionWaitWake({ companyId, agentId, issueId });

    // No `issueRecoveryActions` row exists, so the `exists(...)` fails and
    // `resumeExecutionWaitComments` selects nothing.
    const [recoveryAction] = await db
      .select({ id: issueRecoveryActions.id })
      .from(issueRecoveryActions)
      .where(eq(issueRecoveryActions.sourceIssueId, issueId));
    expect(recoveryAction).toBeUndefined();

    // And the sweep alone does not invent one: clearing a lock is not recovery.
    const orphanRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: orphanRunId,
      companyId,
      agentId,
      status: "interrupted",
      runtimeMode: "legacy",
      invocationSource: "automation",
      contextSnapshot: { issueId },
      finishedAt: new Date("2026-11-04T09:02:00.000Z"),
    });
    await db.update(issues)
      .set({ executionRunId: orphanRunId })
      .where(eq(issues.id, issueId));
    await heartbeatService(db).sweepStaleIssueLocks();

    const [afterSweep] = await db
      .select({ id: issueRecoveryActions.id })
      .from(issueRecoveryActions)
      .where(eq(issueRecoveryActions.sourceIssueId, issueId));
    expect(afterSweep).toBeUndefined();
  });

  it("recoveryService without the release dependency still clears the lock (D1 wiring is optional)", async () => {
    // `releaseClearedIssueExecution` is optional, so a caller that does not wire
    // it keeps the previous self-heal behaviour instead of failing the sweep.
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    const staleRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: staleRunId,
      companyId,
      agentId,
      status: "failed",
      runtimeMode: "legacy",
      invocationSource: "automation",
      finishedAt: new Date("2026-11-04T09:02:00.000Z"),
      contextSnapshot: { issueId },
    });
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Caller without the release dependency",
      status: "todo",
      priority: "high",
      assigneeAgentId: agentId,
      checkoutRunId: staleRunId,
    });

    const result = await recoveryService(db, { enqueueWakeup: vi.fn() }).sweepStaleIssueLocks();

    expect(result.cleared).toBe(1);
    expect(result.drainedRunIds).toEqual([]);
    expect(result.drainFailures).toEqual([]);
  });

  it("releases the orphaned run's environment lease before clearing the lock (D5)", async () => {
    // The measured root cause, not the orphan queue. `getExecutionBlocker`
    // returns two families: an unreleased environment lease (family 1, which
    // carries `recoveryActionId: null`) and an `issueRecoveryActions` row
    // satisfying `executionBlockerPredicate()` (family 2). A run the sweep
    // terminalizes but whose lease is never released keeps reporting
    // `execution_owner_active`, and the release admission declines on any
    // blocker — so widening the wake predicate cannot drain the queue while the
    // lease holds. Every other finalization path releases the lease first
    // (`releaseEnvironmentLeasesForRun` in `scanSilentActiveRuns` and in the
    // process-loss finalizer); the sweep released neither.
    //
    // What this test proves is the sweep's own contract: the native release is
    // invoked for exactly the runs the sweep terminalized, and it happens before
    // the lock clear. Whether the native release then updates a given lease row
    // is `releaseRunLeases`' business, not the sweep's.
    //
    // Fixture independent: every id and time here is generated.
    const order: string[] = [];
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    const orphanRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: orphanRunId,
      companyId,
      agentId,
      status: "running",
      runtimeMode: "legacy",
      invocationSource: "automation",
      // A pid above the system maximum is the repo's own convention for a run
      // whose process is provably gone, which is what lets the sweep's
      // process-death authority terminalize it.
      processPid: 2_000_000_000,
      processStartedAt: new Date("2026-11-04T08:50:00.000Z"),
      contextSnapshot: { issueId, wakeReason: "issue_commented" },
      startedAt: new Date("2026-11-04T08:50:00.000Z"),
    });
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Issue held by a lease whose run the sweep terminalizes",
      status: "in_progress",
      priority: "high",
      assigneeAgentId: agentId,
      executionRunId: orphanRunId,
    });
    const leaseId = randomUUID();
    await db.insert(environmentLeases).values({
      id: leaseId,
      companyId,
      issueId,
      heartbeatRunId: orphanRunId,
      status: "active",
      acquiredAt: new Date("2026-11-04T08:50:00.000Z"),
    });

    const result = await recoveryService(db, {
      enqueueWakeup: vi.fn(),
      releaseTerminalizedRunLeases: async (input) => {
        order.push(`lease:${input.runId}`);
        expect(input).toMatchObject({ companyId, agentId, runId: orphanRunId });
      },
      releaseClearedIssueExecution: async (input) => {
        order.push(`drain:${input.runId}`);
      },
    }).sweepStaleIssueLocks();

    expect(result.terminalizedRunIds).toEqual([orphanRunId]);
    expect(result.releasedLeaseRunIds).toEqual([orphanRunId]);
    expect(result.leaseReleaseFailures).toEqual([]);
    // Lease first, drain second: the same order every other finalization path
    // uses, and the reason the drain can succeed at all.
    expect(order).toEqual([`lease:${orphanRunId}`, `drain:${orphanRunId}`]);
  });

  it("a lease release failure does not abort the sweep or lose the terminalization", async () => {
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    const orphanRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: orphanRunId,
      companyId,
      agentId,
      status: "running",
      runtimeMode: "legacy",
      invocationSource: "automation",
      processPid: 2_000_000_000,
      processStartedAt: new Date("2026-11-04T08:50:00.000Z"),
      contextSnapshot: { issueId },
      startedAt: new Date("2026-11-04T08:50:00.000Z"),
    });
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Lease release raises during the sweep",
      status: "in_progress",
      priority: "high",
      assigneeAgentId: agentId,
      executionRunId: orphanRunId,
    });

    const result = await recoveryService(db, {
      enqueueWakeup: vi.fn(),
      releaseTerminalizedRunLeases: vi.fn(async () => {
        throw new Error("simulated lease release failure");
      }),
    }).sweepStaleIssueLocks();

    // The terminalization stands and the lock still clears: a lease that cannot
    // be released is reported, not swallowed, and not fatal.
    expect(result.terminalizedRunIds).toEqual([orphanRunId]);
    expect(result.releasedLeaseRunIds).toEqual([]);
    expect(result.leaseReleaseFailures).toEqual([orphanRunId]);
    const [row] = await db
      .select({ executionRunId: issues.executionRunId })
      .from(issues)
      .where(eq(issues.id, issueId));
    expect(row?.executionRunId).toBeNull();
  });

  it("does not release the lease of a run it did not terminalize", async () => {
    // A run that was already terminal is not the sweep's to finalize, so its
    // lease stays with whichever path owns it. Releasing it here would let the
    // sweep override a live ownership hold it never proved.
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    const terminalRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: terminalRunId,
      companyId,
      agentId,
      status: "succeeded",
      runtimeMode: "legacy",
      invocationSource: "automation",
      contextSnapshot: { issueId },
      finishedAt: new Date("2026-11-04T09:02:00.000Z"),
    });
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Already-terminal run keeps its lease until its own path releases it",
      status: "in_progress",
      priority: "high",
      assigneeAgentId: agentId,
      executionRunId: terminalRunId,
    });
    const release = vi.fn(async () => {});
    await recoveryService(db, {
      enqueueWakeup: vi.fn(),
      releaseTerminalizedRunLeases: release,
    }).sweepStaleIssueLocks();

    expect(release).not.toHaveBeenCalled();
  });

  it("a failed drain leaves the lock cleared and records the failure (D1 does not abort the sweep)", async () => {
    const { companyId, agentId } = await seed();
    const issueId = randomUUID();
    const staleRunId = randomUUID();
    await db.insert(heartbeatRuns).values({
      id: staleRunId,
      companyId,
      agentId,
      status: "interrupted",
      runtimeMode: "legacy",
      invocationSource: "automation",
      contextSnapshot: { issueId },
      finishedAt: new Date("2026-11-04T09:02:00.000Z"),
    });
    await db.insert(issues).values({
      id: issueId,
      companyId,
      title: "Drain raises during the sweep",
      status: "in_progress",
      priority: "high",
      assigneeAgentId: agentId,
      executionRunId: staleRunId,
    });

    const result = await recoveryService(db, {
      enqueueWakeup: vi.fn(),
      releaseClearedIssueExecution: vi.fn(async () => {
        throw new Error("simulated drain failure");
      }),
    }).sweepStaleIssueLocks();

    expect(result.cleared).toBe(1);
    expect(result.drainedRunIds).toEqual([]);
    expect(result.drainFailures).toEqual([staleRunId]);
    const [row] = await db
      .select({ executionRunId: issues.executionRunId })
      .from(issues)
      .where(eq(issues.id, issueId));
    expect(row?.executionRunId).toBeNull();
  });
});
